pub(crate) fn emit_expr_int_text(value: u64, negative: bool) -> String {
    if negative && value != 0u64 { return format!("-{}", value); }
    format!("{}", value)
}

pub(crate) fn emit_expr_integer_literal(value: u64, negative: bool, widen: bool) -> String {
    let text = emit_expr_int_text(value, negative);
    let fits_i32 = if negative { value <= 2147483648u64 } else { value <= 2147483647u64 };
    if fits_i32 && !widen { return text; }
    let fits_i64 = negative || value <= 9223372036854775807u64;
    if fits_i64 { return format!("{}i64", text); }
    format!("{}u64", text)
}

pub(crate) fn emit_expr_kept_text(world: &EmitWorld<'_, '_, '_, '_>, func: &Expr) -> String {
    match func {
        Expr::Path(segments, _) => {
            let mut parts: Vec<String> = vec![];
            for s in segments.iter() {
                let s = *s;
                parts.push(emit_text(world, s));
            }
            parts.join("::")
        },
        Expr::Variable(name, _) => { let name = *name; emit_text(world, name) },
        _ => String::from(""),
    }
}

